35: function updateUnitPanel(){const box=document.getElementById('unitPanel'),u=units.find(v=>v.id===selected),moveBtn=document.getElementById('moveBtn'),fireBtn=document.getElementById('fireBtn');if(!u){box.className='unit-empty';box.innerHTML='Select one of your units<br>on the battlefield to inspect it.';document.getElementById('unitCoord').textContent='—';moveBtn.disabled=true;fireBtn.disabled=true;moveBtn.classList.remove('active');fireBtn.classList.remove('active');return}const d=unitTypes[u.type],own=u.side===player;box.className='unit-content';box.innerHTML=`<div class="unit-top"><div class="unit-icon" style="color:${factionData[u.side].color}">${d.symbol}</div><div><div class="unit-name">${d.name}</div><div class="unit-sub">${factionData[u.side].name} · ${own?'YOUR UNIT':'ENEMY UNIT'}</div></div></div><div class="hp-label"><span>STRENGTH</span><span>${u.hp} / ${u.maxHp}</span></div><div class="hp-bar"><div style="width:${u.hp/u.maxHp*100}%;background:${u.hp/u.maxHp<.35?'#cf6858':'#9cad73'}"></div></div><div class="unit-stats"><span>MOVE <b>${u.moveLeft}</b></span><span>RANGE <b>${d.range}</b></span><span>FIRE <b>${u.attacked?'SPENT':'READY'}</b></span></div><div class="unit-desc">${d.desc}</div>`;document.getElementById('unitCoord').textContent=`${String.fromCharCode(65+u.x)}${u.y+1}`;moveBtn.disabled=!own||u.moveLeft<=0||busy;fireBtn.disabled=!own||u.attacked||busy;moveBtn.classList.toggle('active',mode==='move');fireBtn.classList.toggle('active',mode==='fire')}
