38: function reachable(u){let dist=Array.from({length:H},()=>Array(W).fill(Infinity));dist[u.y][u.x]=0;let q=[[u.x,u.y]];while(q.length){q.sort((a,b)=>dist[a[1]][a[0]]-dist[b[1]][b[0]]);let [x,y]=q.shift();for(let[dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy;if(nx<0||nx>=W||ny<0||ny>=H)continue;let occ=unitAt(nx,ny);if(occ&&occ.id!==u.id)continue;let nd=dist[y][x]+moveCosts(nx,ny);if(nd<=u.moveLeft&&nd<dist[ny][nx]){dist[ny][nx]=nd;q.push([nx,ny])}}}return dist}
