42: function handleTile(x,y){let u=units.find(v=>v.id===selected),target=unitAt(x,y);if(mode==='move'&&u&&u.side===player){if(!target||target.id===u.id){let dist=reachable(u);if(dist[y][x]<=u.moveLeft&&dist[y][x]>0){let cost=dist[y][x];u.x=x;u.y=y;u.moveLeft-=cost;u.moved=true;mode=null;log(`${unitTypes[u.type].name} advances to ${String.fromCharCode(65+x)}${y+1}.`);afterAction();return}else toast('That position is out of reach.')}else toast('A unit blocks that position.');return}if(mode==='fire'&&u&&u.side===player){if(target&&target.side!==player){if(!inRange(u,target)){toast('Target outside firing range.');return}fireAt(u,target);mode=null;afterAction();return}else{toast('Select an enemy unit to fire at.');return}}if(target&&target.side===player){selected=target.id;mode=null;updateUnitPanel();render();return}if(target&&target.side!==player&&u&&u.side===player&&!u.attacked&&inRange(u,target)){fireAt(u,target);mode=null;afterAction();return}if(!target&&u&&u.side===player&&u.moveLeft>0){let dist=reachable(u);if(dist[y][x]>0&&dist[y][x]<=u.moveLeft){u.x=x;u.y=y;u.moveLeft-=dist[y][x];u.moved=true;mode=null;log(`${unitTypes[u.type].name} advances.`);afterAction();return}}selected=null;mode=null;updateUnitPanel();render()}
