46: function enemyTurn(){let enemy=player==='sov'?'ger':'sov',actors=units.filter(u=>u.side===enemy).slice();for(let u of actors){if(!units.includes(u))continue;let targets=units.filter(v=>v.side===player),candidate=targets.filter(t=>inRange(u,t)).sort((a,b)=>a.hp-b.hp)[0];if(candidate&&!u.attacked){resolveFire(u,candidate);continue}if(u.moveLeft>0){let options=[];for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(unitAt(x,y)&&!(u.x===x&&u.y===y))continue;let d=Math.abs(u.x-x)+Math.abs(u.y-y);if(d>u.moveLeft||d===0)continue;let objDist=Math.min(...objectives.map(o=>Math.abs(o.x-x)+Math.abs(o.y-y))),enemyDist=targets.length?Math.min(...targets.map(t=>Math.abs(t.x-x)+Math.abs(t.y-y))):99,value=-objDist*.8-enemyDist*.16+rnd(x+u.id.length,y+turn)*.18;options.push({x,y,value})}options.sort((a,b)=>b.value-a.value);if(options[0]){u.x=options[0].x;u.y=options[0].y;u.moveLeft=0}}let after=units.filter(v=>v.side===player).filter(t=>inRange(u,t)).sort((a,b)=>a.hp-b.hp)[0];if(after&&!u.attacked)resolveFire(u,after)}objectives.forEach(o=>{let before=o.owner;o.owner=objectiveOwner(o);if(o.owner!==before&&o.owner)log(`${o.name} taken by ${factionData[o.owner].name}.`,'alert')});let pcount=objectives.filter(o=>o.owner===player).length,ecount=objectives.filter(o=>o.owner===enemy).length;if(pcount>ecount){score[player]+=2;log('Your command controls the field. +2 victory points.')}else if(ecount>pcount){score[enemy]+=2;log('Enemy command controls the field. Enemy gains +2 VP.','alert')}else log('The strategic points remain contested.');if(checkWinner())return;turn++;for(let u of units){u.moveLeft=unitTypes[u.type].move;u.attacked=false;u.moved=false}busy=false;setUI();render();toast('Your orders, commander.')}
47: function resolveFire(a,b){let dmg=Math.max(1,unitTypes[a.type].damage-(b.type==='tank'&&a.type==='rifle'?1:0));if(terrain[b.y][b.x]==='factory'||terrain[b.y][b.x]==='rubble')dmg=Math.max(1,dmg-1);b.hp-=dmg;a.attacked=true;log(`Enemy ${unitTypes[a.type].name} fires — ${dmg} strength lost.`, 'alert');if(b.hp<=0){log(`Your ${unitTypes[b.type].name} has been destroyed.`, 'alert');units=units.filter(v=>v.hp>0)}}
